using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class RemainingApply {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B5/",P=A+"Props/B5/";static string Repo=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static Dictionary<string,Material> mats=new Dictionary<string,Material>();static Transform root,group;static JObject plan;static List<string> archived=new List<string>();
 static Vector3 V(JToken v)=>new Vector3((float)v[0],(float)v[1],(float)v[2]);static GameObject Child(string n,Transform p){var g=new GameObject(n);g.transform.SetParent(p,false);return g;}
 static Material Mat(string key,Color c,float metal,float smooth,string copy=null){string path=P+"Materials/RD_"+key+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(!m){var src=copy==null?null:AssetDatabase.LoadAssetAtPath<Material>(copy);m=src?new Material(src):new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(m,path);}m.name="RD_"+key;m.SetColor("_BaseColor",c);if(copy==null){m.SetFloat("_Metallic",metal);m.SetFloat("_Smoothness",smooth);}m.DisableKeyword("_EMISSION");m.SetColor("_EmissionColor",Color.black);if(key.StartsWith("Display_")){var tex=AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/RD_"+key+".png");m.SetTexture("_BaseMap",tex);m.SetTexture("_EmissionMap",tex);m.SetColor("_EmissionColor",Color.white*.75f);m.EnableKeyword("_EMISSION");m.SetFloat("_SpecularHighlights",0);m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.None;}if(key=="Lamp"||key=="Indicator"){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",c*(key=="Lamp"?2.5f:.5f));m.globalIlluminationFlags=MaterialGlobalIlluminationFlags.None;}if(key=="Glass"){m.SetFloat("_Surface",1);m.SetFloat("_SrcBlend",(float)BlendMode.SrcAlpha);m.SetFloat("_DstBlend",(float)BlendMode.OneMinusSrcAlpha);m.SetFloat("_ZWrite",0);m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");m.SetOverrideTag("RenderType","Transparent");m.renderQueue=3000;}if(key=="Fabric"){m.SetTexture("_BaseMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/RD_Fabric_Base.png"));m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/RD_Fabric_Normal.png"));m.SetFloat("_BumpScale",.25f);m.EnableKeyword("_NORMALMAP");m.SetTexture("_MetallicGlossMap",AssetDatabase.LoadAssetAtPath<Texture2D>(P+"Textures/RD_Fabric_MetalSmooth.png"));m.EnableKeyword("_METALLICSPECGLOSSMAP");}EditorUtility.SetDirty(m);AssetDatabase.SaveAssetIfDirty(m);mats[m.name]=m;return m;}
 static void Materials(){foreach(var f in Directory.GetFiles(Path.Combine(Application.dataPath,"Afrer_Seconds/05.Model/Props/B5/Textures"),"RD_*.png")){var p=P+"Textures/"+Path.GetFileName(f);AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);var ti=(TextureImporter)AssetImporter.GetAtPath(p);ti.textureType=p.Contains("Normal")?TextureImporterType.NormalMap:TextureImporterType.Default;ti.sRGBTexture=!p.Contains("MetalSmooth");ti.mipmapEnabled=true;ti.maxTextureSize=2048;ti.filterMode=FilterMode.Trilinear;ti.wrapMode=p.Contains("Display")?TextureWrapMode.Clamp:TextureWrapMode.Repeat;ti.SaveAndReimport();}
 Mat("Coat",Color.white,.12f,.52f,E+"Materials/TC_Coat.mat");Mat("Steel",Color.white,.8f,.66f,E+"Materials/TC_Steel.mat");Mat("Floor",Color.white,.02f,.32f,E+"Materials/TC_Floor.mat");Mat("Dark",new Color(.026f,.04f,.05f),.15f,.48f);Mat("Rubber",new Color(.016f,.022f,.025f),0,.27f);Mat("Teal",new Color(.08f,.24f,.26f),.4f,.6f);Mat("Fabric",Color.white,0,.12f);Mat("Glass",new Color(.08f,.18f,.20f,.16f),.15f,.84f);Mat("Indicator",new Color(.19f,.67f,.48f),.1f,.7f);Mat("Paper",new Color(.74f,.76f,.70f),0,.12f);Mat("Lamp",new Color(.75f,.85f,.88f),0,.8f);Mat("Warm",new Color(.55f,.45f,.29f),.1f,.42f);Mat("Red",new Color(.47f,.13f,.1f),.05f,.4f);Mat("Hazard",new Color(.77f,.62f,.21f),.05f,.4f);for(int i=1;i<=18;i++)Mat("Display_"+i.ToString("00"),Color.white,0,.3f);}
 static void Import(){foreach(var folder in new[]{E,P})foreach(var file in Directory.GetFiles(Path.Combine(Application.dataPath,"..",folder),"RD_*.fbx")){string path=folder+Path.GetFileName(file);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var mi=(ModelImporter)AssetImporter.GetAtPath(path);mi.importAnimation=false;mi.importCameras=false;mi.importLights=false;mi.isReadable=true;mi.importNormals=ModelImporterNormals.Import;mi.importTangents=ModelImporterTangents.CalculateMikk;mi.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;foreach(var p in mats)mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),p.Key),p.Value);mi.SaveAndReimport();}}
 static GameObject Model(string n,Transform parent,bool env=false,bool collide=false){var src=AssetDatabase.LoadAssetAtPath<GameObject>((env?E:P)+n+".fbx");if(!src)throw new Exception("Missing "+n);var go=(GameObject)PrefabUtility.InstantiatePrefab(src,parent);go.name=n;go.transform.localPosition=Vector3.zero;go.transform.localRotation=Quaternion.identity;go.transform.localScale=Vector3.one;foreach(var rr in go.GetComponentsInChildren<Renderer>())rr.sharedMaterials=rr.sharedMaterials.Select(m=>mats[m.name]).ToArray();if(collide){var meshes=go.GetComponentsInChildren<MeshFilter>();if(n.Contains("Alcove")||n.Contains("Shower")||n.Contains("Gantry")){foreach(var mf in meshes)mf.gameObject.AddComponent<MeshCollider>().sharedMesh=mf.sharedMesh;}else{var b=meshes[0].sharedMesh.bounds;foreach(var mf in meshes.Skip(1))b.Encapsulate(mf.sharedMesh.bounds);var bc=go.AddComponent<BoxCollider>();bc.center=b.center;bc.size=b.size;}}return go;}
 static void Archive(Transform t){if(t&&t.gameObject.activeSelf){t.gameObject.SetActive(false);archived.Add(t.name);}}
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 Edit required");root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;if(root.Find("Remaining_Domes_Art"))throw new Exception("Already applied; targeted repair required");plan=JObject.Parse(File.ReadAllText(Repo+"/SourceAssets/B5_RemainingDomes/plan.json"));Materials();Import();group=Child("Remaining_Domes_Art",root).transform;group.localPosition=Vector3.zero;Undo.RegisterCreatedObjectUndo(group.gameObject,"Remaining B5 domes");
 foreach(string code in plan["construction"].Values<string>().Where(c=>c!="VB"&&c!="VL")){var r=plan["rooms"][code];var room=Child(code,group).transform;room.position=V(r["position"]);foreach(string part in new[]{"Architecture","Floor","Services"})Model("RD_"+code+"_"+part,room,true);foreach(var p in plan["placements"].Where(p=>(string)p["room"]==code)){var g=Model((string)p["model"],room,false,(bool)p["collision"]);g.name=(string)p["id"];g.transform.localPosition=V(p["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)p["yaw"],0);}}
 foreach(var t in plan["tunnels"].Skip(2)){var room=Child((string)t["id"],group).transform;var p=t["p"];var q=t["q"];room.position=new Vector3((float)p[0],-82,-(float)p[1]);var end=new Vector3((float)q[0],-82,-(float)q[1]);room.rotation=Quaternion.LookRotation(end-room.position);Model("RD_"+((string)t["id"]).Replace("B5-","")+"_Finish",room,true);float len=Vector3.Distance(room.position,end);foreach(float x in new[]{-1.98f,1.98f}){var c=Child("Cart_Rail_Collision",room).AddComponent<BoxCollider>();c.center=new Vector3(x,.94f,len/2);c.size=new Vector3(.15f,.11f,len-1.2f);}var box=Child("Control_Collision",room).AddComponent<BoxCollider>();box.center=new Vector3(1.94f,1.54f,len*.45f);box.size=new Vector3(.25f,.82f,.64f);}
 Archive(root.Find("B5_FullLayout_Implementation/Outer_Caverns_Props"));foreach(var t in root.Find("Existing_Props_FirstPass").Cast<Transform>()){var p=t.position;if(Vector2.Distance(new Vector2(p.x,p.z),new Vector2(17,-7))<10.1f||Vector2.Distance(new Vector2(p.x,p.z),new Vector2(16,20))<6.1f)Archive(t);}
 var doors=root.Find("Pocket_Doors_Open");var template=doors.Find("Door_B5-T02_2/Clinical_Portal");int count=0;foreach(var tun in plan["tunnels"].Skip(2))foreach(string end in new[]{"p","q"}){var v=tun[end];var pos=new Vector3((float)v[0],-82,-(float)v[1]);var dst=doors.Cast<Transform>().OrderBy(t=>Vector3.Distance(t.position,pos)).First();if(Vector3.Distance(dst.position,pos)>.01f)throw new Exception("Door missing "+tun["id"]+end);if(dst.Find("Clinical_Portal"))continue;var archive=Child("Previous_Rectangular_Door_Inactive",dst).transform;foreach(var t in dst.Cast<Transform>().Where(t=>t!=archive).ToArray())t.SetParent(archive,true);archive.gameObject.SetActive(false);var g=UnityEngine.Object.Instantiate(template.gameObject,dst);g.name="Clinical_Portal";g.transform.localPosition=Vector3.zero;string code=(string)tun[end=="p"?"a":"b"];var center=V(plan["rooms"][code]["position"]);g.transform.rotation=Quaternion.LookRotation((dst.position-center).normalized);g.transform.localScale=Vector3.one;count++;}
 var chairSrc=AssetDatabase.LoadAssetAtPath<GameObject>(P+"SC_TaskChair.fbx");foreach(float x in new[]{-2.6f,0,2.6f}){var g=(GameObject)PrefabUtility.InstantiatePrefab(chairSrc,group.Find("N01"));g.name="N01_OperatorChair_"+x;g.transform.localPosition=new Vector3(x,0,2.55f);var c=g.AddComponent<BoxCollider>();c.center=new Vector3(0,.58f,0);c.size=new Vector3(.68f,1.16f,.70f);}
 Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(s);EditorSceneManager.SaveScene(s);var result=new{scene=s.path,domes=10,props=plan["placements"].Count(),corridors=17,newDoors=count,archived,renderers=group.GetComponentsInChildren<Renderer>().Length,colliders=group.GetComponentsInChildren<Collider>().Length,lights=root.GetComponentsInChildren<Light>(true).Length};File.WriteAllText(Repo+"/Docs/검수/2026-11-08_B5_RemainingDomes/apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
